package e.e.a;
import android.content.*;import android.view.*;import android.widget.*;
/** Shared fixed selection footer; the list keeps all remaining height. */
final class SelectionUi191 {
 static LinearLayout footer(Context c,Runnable delete,Runnable done){LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER_VERTICAL);int p=PanelUi.dp(c,12);row.setPadding(p,PanelUi.dp(c,4),p,PanelUi.dp(c,4));Button remove=PanelUi.button(c,UiStrings.translate("削除"));UiDialogs.actionButton(remove,true);remove.setOnClickListener(v->delete.run());row.addView(remove,new LinearLayout.LayoutParams(-2,PanelUi.dp(c,48)));row.addView(new View(c),new LinearLayout.LayoutParams(0,1,1));Button finish=PanelUi.button(c,UiStrings.translate("完了"));UiDialogs.actionButton(finish,false);finish.setTextColor(PanelUi.ink(c));finish.setOnClickListener(v->done.run());row.addView(finish,new LinearLayout.LayoutParams(-2,PanelUi.dp(c,48)));insets(row);return row;}
 static void insets(View footer){final int left=footer.getPaddingLeft(),top=footer.getPaddingTop(),right=footer.getPaddingRight(),bottom=footer.getPaddingBottom();Runnable update=()->{if(footer.getWindowToken()==null)return;android.graphics.Rect visible=new android.graphics.Rect();footer.getWindowVisibleDisplayFrame(visible);int[] xy=new int[2];footer.getLocationOnScreen(xy);int overlap=Math.max(0,xy[1]+footer.getHeight()-visible.bottom);int padding=bottom+overlap;if(footer.getPaddingBottom()!=padding)footer.setPadding(left,top,right,padding);};footer.addOnLayoutChangeListener((v,l,t,r,b,ol,ot,orr,ob)->update.run());footer.setOnApplyWindowInsetsListener((v,windowInsets)->{v.post(update);return windowInsets;});footer.post(update);}
 static void count(TextView label,int count){label.setText(BulkSelection.countText(label.getContext(),count));}
 static void enabled(LinearLayout footer,int count){if(footer!=null)footer.getChildAt(0).setEnabled(count>0);}
 static void menu(Menu menu,Context c,Runnable all,Runnable clear,Runnable move){menu.add(UiStrings.translate("全選択")).setOnMenuItemClickListener(i->{all.run();return true;});menu.add(UiStrings.translate("全解除")).setOnMenuItemClickListener(i->{clear.run();return true;});if(move!=null)menu.add(UiStrings.translate("移動")).setOnMenuItemClickListener(i->{move.run();return true;});}
}
